add_filter( 'ngettext_woocommerce', 'perfectpixel_rename_meta_labels', 10, 4 );

function perfectpixel_rename_meta_labels( $translation, $single, $plural, $number ) {
	$map = array(
		'Category:' => array( '{{cat_label_single}}', '{{cat_label_plural}}' ),
		'Tag:'      => array( '{{tag_label_single}}', '{{tag_label_plural}}' ),
	);
	if ( isset( $map[ $single ] ) ) {
		$custom = 1 === (int) $number ? $map[ $single ][0] : $map[ $single ][1];
		if ( '' !== trim( $custom ) ) {
			return $custom;
		}
	}
	return $translation;
}
